package com.example.library.service;
import com.example.library.model.*;import com.example.library.repo.*;import java.time.LocalDate;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.cache.annotation.CacheEvict;import org.springframework.transaction.annotation.Transactional;
@Service public class BorrowService {private final BorrowRepository borrows;private final BookRepository books;private final UserRepository users;public BorrowService(BorrowRepository b,BookRepository bk,UserRepository u){borrows=b;books=bk;users=u;}
 @CacheEvict(value="books",allEntries=true) @Transactional public BorrowRecord borrow(Long bookId,String username){AppUser user=users.findByUsername(username).orElseThrow(()->new IllegalArgumentException("User not found"));Book book=books.findById(bookId).orElseThrow(()->new IllegalArgumentException("Book not found"));if(book.getAvailableQuantity()<1)throw new IllegalArgumentException("No copies available");book.setAvailableQuantity(book.getAvailableQuantity()-1);BorrowRecord r=new BorrowRecord();r.setBook(book);r.setUser(user);return borrows.save(r);}
 @CacheEvict(value="books",allEntries=true) @Transactional public BorrowRecord returnBook(Long recordId,String username,boolean admin){BorrowRecord r=borrows.findById(recordId).orElseThrow(()->new IllegalArgumentException("Borrow record not found"));if(!admin&&!r.getUser().getUsername().equals(username))throw new org.springframework.security.access.AccessDeniedException("This is not your borrowing record");if(r.getReturnDate()!=null)throw new IllegalArgumentException("Book already returned");r.setReturnDate(LocalDate.now());r.getBook().setAvailableQuantity(r.getBook().getAvailableQuantity()+1);return borrows.save(r);}
 public List<BorrowRecord> mine(String username){AppUser u=users.findByUsername(username).orElseThrow(()->new IllegalArgumentException("User not found"));return borrows.findByUserIdOrderByBorrowDateDesc(u.getId());}
 public List<BorrowRecord> all(){return borrows.findAll();}
}
